package core_test

import (
	"context"
	"os"
	"path/filepath"
	"testing"

	"github.com/pocketbase/pocketbase/tests"
)

// Backup generated by an unmodified PocketBase v0.41.1 (a base collection,
// a view and 3 records; types.d.ts removed to keep the fixture small).
func TestRestorePocketBase0411Backup(t *testing.T) {
	app, _ := tests.NewTestApp(t)
	defer app.Cleanup()

	src := filepath.Join("testdata", "pb_v0_41_1_backup.zip")
	data, err := os.ReadFile(src)
	if err != nil {
		t.Fatal(err)
	}
	if err := os.MkdirAll(app.DataDir()+"/backups", 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(app.DataDir()+"/backups/v0411.zip", data, 0o644); err != nil {
		t.Fatal(err)
	}

	if err := app.RestoreBackup(context.Background(), "v0411.zip"); err != nil {
		t.Fatal(err)
	}

	if n := recordCounts(t, app)["posts"]; n != 3 {
		t.Fatalf("expected 3 posts, got %d", n)
	}
	if _, err := app.FindCollectionByNameOrId("vposts"); err != nil {
		t.Fatalf("expected the view to be imported: %v", err)
	}
	if _, err := app.FindFirstRecordByFilter("vposts", "title='p2'"); err != nil {
		t.Fatalf("view query failed: %v", err)
	}
}
